import ast
from types import SimpleNamespace
from typing import Any

path = "vllm/utils/torch_utils.py"
tree = ast.parse(open(path, encoding="utf-8").read(), path)
wanted = {"get_kv_cache_quant_algo_string", "resolve_kv_cache_dtype_string"}
module = ast.Module(
    body=[node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name in wanted],
    type_ignores=[],
)
class Logger:
    def warning(self, *args):
        pass
namespace = {
    "Any": Any,
    "ModelConfig": object,
    "logger": Logger(),
    "MODELOPT_TO_VLLM_KV_CACHE_DTYPE_MAP": {"fp8": "fp8_e4m3", "nvfp4": "nvfp4"},
}
exec(compile(module, path, "exec"), namespace)
resolve = namespace["resolve_kv_cache_dtype_string"]
def config(algo=None):
    quant = {"quant_method": "modelopt"}
    if algo is not None:
        quant["quantization"] = {"kv_cache_quant_algo": algo}
    return SimpleNamespace(hf_config=SimpleNamespace(quantization_config=quant))
assert resolve("auto", config("FP8")) == "fp8_e4m3"
assert resolve("fp8", config("FP8")) == "fp8_e4m3"
assert resolve("fp8_e4m3", config("FP8")) == "fp8_e4m3"
assert resolve("auto", config()) == "auto"
assert resolve("bfloat16", config()) == "bfloat16"
try:
    resolve("bfloat16", config("FP8"))
except ValueError as exc:
    assert "--kv-cache-dtype auto" in str(exc)
else:
    raise AssertionError("incompatible override was accepted")
print("7 CPU configuration assertions passed")
PY
